import{_ as e,C as t,c as r,o as l,a0 as n,b as a,w as i,a as s,G as o,a1 as d}from"./chunks/framework.DKRgXLPU.js";const m=JSON.parse('{"title":"Målsetting for petanquespillere","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/goals/index.md","filePath":"no/education/goals/index.md"}');const g=e({name:"no/education/goals/index.md"},[["render",function(e,m,g,p,u,k){const h=t("Mermaid");return l(),r("div",null,[m[1]||(m[1]=n('<h1 id="malsetting-for-petanquespillere" tabindex="-1">Målsetting for petanquespillere <a class="header-anchor" href="#malsetting-for-petanquespillere" aria-label="Permalink to &quot;Målsetting for petanquespillere&quot;">​</a></h1><p>Tydelige mål er kompasset ditt. De gir retning til treningen din, motivasjon når ting blir vanskelige, og en måte å måle fremgang på. Uten mål kaster du bare boccia. Med mål bygger du mot noe.</p><div class="tip custom-block"><p class="custom-block-title">Kjerneprinsippet</p><p><strong>Et mål uten en plan er bare et ønske.</strong> Sett deg klare mål, del dem opp, fokuser på det du kontrollerer og følg fremgangen din.</p></div><h2 id="hvorfor-mal-er-viktige" tabindex="-1">Hvorfor mål er viktige <a class="header-anchor" href="#hvorfor-mal-er-viktige" aria-label="Permalink to &quot;Hvorfor mål er viktige&quot;">​</a></h2><p>Mål tjener flere formål:</p><ul><li><strong>Retning:</strong> Vit hva du skal jobbe med</li><li><strong>Motivasjon:</strong> Ha noe å strebe etter</li><li><strong>Måling:</strong> Spor fremgangen din</li><li><strong>Fokus:</strong> Prioriter din begrensede tid</li></ul><p>For den selvstyrte spilleren er mål spesielt viktige. Uten en trener som presser deg, blir målene dine din veileder.</p><h2 id="de-tre-typene-mal" tabindex="-1">De tre typene mål <a class="header-anchor" href="#de-tre-typene-mal" aria-label="Permalink to &quot;De tre typene mål&quot;">​</a></h2><p>Ikke alle mål er like. Å forstå de ulike typene hjelper deg med å sette deg bedre mål.</p><h3 id="_1-resultatmal" tabindex="-1">1. Resultatmål <a class="header-anchor" href="#_1-resultatmal" aria-label="Permalink to &quot;1. Resultatmål&quot;">​</a></h3><p><strong>Hva:</strong> Sluttresultatet du ønsker <strong>Eksempel:</strong> «Vinn regionmesterskapet» <strong>Kontrollnivå:</strong> Lav – avhenger av motstandere, forhold og flaks</p><h3 id="_2-prestasjonsmal" tabindex="-1">2. Prestasjonsmål <a class="header-anchor" href="#_2-prestasjonsmal" aria-label="Permalink to &quot;2. Prestasjonsmål&quot;">​</a></h3><p><strong>Hva:</strong> Spesifikke ytelsesstandarder <strong>Eksempel:</strong> «Oppnå 80 % nøyaktighet på skyteøvelser» <strong>Kontrollnivå:</strong> Middels – avhenger stort sett av deg</p><h3 id="_3-prosessmal" tabindex="-1">3. Prosessmål <a class="header-anchor" href="#_3-prosessmal" aria-label="Permalink to &quot;3. Prosessmål&quot;">​</a></h3><p><strong>Hva:</strong> Handlinger og atferd du kontrollerer <strong>Eksempel:</strong> «Fullfør rutinen min før skuddet på hvert kast» <strong>Kontrollnivå:</strong> Høyt – helt opp til deg</p><h3 id="malhierarkiet" tabindex="-1">Målhierarkiet <a class="header-anchor" href="#malhierarkiet" aria-label="Permalink to &quot;Målhierarkiet&quot;">​</a></h3>',16)),(l(),a(d,null,{default:i(()=>[o(h,{id:"mermaid-69",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BResultatm%C3%A5l%20%3Cbr%2F%3E%20Dr%C3%B8mmen%5D%20--%3E%20B%5BYtelsesm%C3%A5l%20%3Cbr%2F%3E%20Milep%C3%A6ler%5D%0A%20%20%20%20B%20--%3E%20C%5BProsess%20m%C3%A5l%20%3Cbr%2F%3E%20Daglige%20handlinger%5D%0A%0A%20%20%20%20A2%5B%26quot%3BVinn%20regionmesterskapet%26quot%3B%5D%20--%3E%20B2%5B%26quot%3B80%20%25%20skytepresisjon%26quot%3B%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%26quot%3BKomplett%20rutine%20f%C3%B8r%20inntak%26quot%3B%20%3Cbr%2F%3E%20hvert%20kast%26quot%3B%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B%20fill%3A%23fff9c4%0A%20%20%20%20style%20C%20fill%3A%23c8e6c9%0A%20%20%20%20style%20A2%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B2%20fill%3A%23fff9c4%0A%20%20%20%20style%20C2%20fill%3A%23c8e6c9%0A"})]),fallback:i(()=>[...m[0]||(m[0]=[s(" Loading... ",-1)])]),_:1})),m[2]||(m[2]=n('<div class="warning custom-block"><p class="custom-block-title">Viktig innsikt</p><p><strong>Fokuser mesteparten av oppmerksomheten din på prosessmål.</strong> Det er de du kontrollerer, og de fører til resultatene du ønsker.</p><ul><li><strong>Resultatmål:</strong> Lav kontroll, høy motivasjon</li><li><strong>Ytelsesmål:</strong> Middels kontroll, målbar fremgang</li><li><strong>Prosessmål:</strong> Høy kontroll, daglig fokus ← <strong>Fokus her</strong></li></ul></div><h2 id="smart-rammeverket" tabindex="-1">SMART-rammeverket <a class="header-anchor" href="#smart-rammeverket" aria-label="Permalink to &quot;SMART-rammeverket&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Sjekkliste for SMART-mål</p><p>Hvert mål bør være:</p><ul><li>✅ **Spesifik - Tydelig og veldefinert</li><li>✅ <strong>Målbar</strong> - Du kan spore fremgangen</li><li>✅ <strong>Oppnåelig</strong> - Utfordrende, men mulig</li><li>✅ **Relevant – i tråd med ditt større bilde</li><li>✅ **Tidsbundet - Har en frist</li></ul></div><h3 id="s-spesifikk" tabindex="-1">S - Spesifikk <a class="header-anchor" href="#s-spesifikk" aria-label="Permalink to &quot;S - Spesifikk&quot;">​</a></h3><p>❌ &quot;Bli bedre til å skyte&quot; ✅ «Forbedre presisjonen min på au fer (direkte treff) fra 8 meter»</p><h3 id="m-malbar" tabindex="-1">M - Målbar <a class="header-anchor" href="#m-malbar" aria-label="Permalink to &quot;M - Målbar&quot;">​</a></h3><p>❌ &quot;Skyt mer presist&quot; ✅ &quot;Score minst 24/30 på skytestigeøvelsen&quot;</p><h3 id="a-oppnaelig" tabindex="-1">A - Oppnåelig <a class="header-anchor" href="#a-oppnaelig" aria-label="Permalink to &quot;A - Oppnåelig&quot;">​</a></h3><p>❌ &quot;Gå aldri glipp av et skudd&quot; (umulig) ✅ «Forbedre nøyaktigheten med 10 % over 8 uker» (utfordrende, men realistisk)</p><h3 id="r-relevant" tabindex="-1">R - Relevant <a class="header-anchor" href="#r-relevant" aria-label="Permalink to &quot;R - Relevant&quot;">​</a></h3><p>❌ «Løp maraton» (ikke direkte relatert) ✅ &quot;Forbedre balanse og stabilitet for bedre kasting&quot; (støtter spillet ditt)</p><h3 id="t-tidsbundet" tabindex="-1">T - Tidsbundet <a class="header-anchor" href="#t-tidsbundet" aria-label="Permalink to &quot;T - Tidsbundet&quot;">​</a></h3><p>❌ «En dag blir jeg bedre» ✅ &quot;Innen 15. mars skal jeg oppnå...&quot;</p><h2 id="eksempler-pa-mal-for-petanque" tabindex="-1">Eksempler på mål for petanque <a class="header-anchor" href="#eksempler-pa-mal-for-petanque" aria-label="Permalink to &quot;Eksempler på mål for petanque&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Dårlig mål</th><th>SMART-mål</th></tr></thead><tbody><tr><td>Utfall</td><td>&quot;Vinn mer&quot;</td><td>&quot;Nå semifinalen i vårturneringen&quot;</td></tr><tr><td>Ytelse</td><td>&quot;Peke bedre&quot;</td><td>&quot;Oppnå 70 % av poengene innenfor 50 cm på 8 m avstand&quot;</td></tr><tr><td>Behandle</td><td>&quot;Øv mer&quot;</td><td>&quot;Fullfør 3 fokuserte treningsøkter per uke&quot;</td></tr></tbody></table><h2 id="a-bryte-ned-store-mal" tabindex="-1">Å bryte ned store mål <a class="header-anchor" href="#a-bryte-ned-store-mal" aria-label="Permalink to &quot;Å bryte ned store mål&quot;">​</a></h2><p>Store mål kan føles overveldende. Del dem opp i mindre biter:</p><h3 id="eksempel-«vinn-klubbmesterskapet-12-maneder-unna-»" tabindex="-1">Eksempel: «Vinn klubbmesterskapet (12 måneder unna)» <a class="header-anchor" href="#eksempel-«vinn-klubbmesterskapet-12-maneder-unna-»" aria-label="Permalink to &quot;Eksempel: «Vinn klubbmesterskapet (12 måneder unna)»&quot;">​</a></h3><p><strong>Årsmål:</strong> Vinn klubbmesterskapet</p><p><strong>Kvartalsvise mål:</strong></p><ul><li>Q1: Forbedre skytepresisjonen til 75 %</li><li>Q2: Utvikle en konsekvent rutine før sprøyting</li><li>Q3: Mesterpresssituasjoner</li><li>Q4: Topp ytelse og konkurranseforberedelser</li></ul><p><strong>Månedlige mål (Q1):</strong></p><ul><li>Måned 1: Etablere grunnlinje, identifisere svakheter</li><li>Måned 2: Fokus på skyteteknikk</li><li>Måned 3: Legg til press på skytetreningen</li></ul><p><strong>Ukentlige mål (måned 2):</strong></p><ul><li>Uke 1: 3 skyteøkter, videoanalyse</li><li>Uke 2: Arbeid med identifisert teknikkproblem</li><li>Uke 3: Øk avstanden gradvis</li><li>Uke 4: Test fremgang, juster planen</li></ul><h2 id="koble-mal-til-ditt-«hvorfor»" tabindex="-1">Koble mål til ditt «hvorfor» <a class="header-anchor" href="#koble-mal-til-ditt-«hvorfor»" aria-label="Permalink to &quot;Koble mål til ditt «hvorfor»&quot;">​</a></h2><p>Mål fungerer bedre når de er koblet til dypere motivasjon.</p><p>Spør deg selv:</p><ul><li>Hvorfor ønsker jeg å oppnå dette?</li><li>Hva vil det bety for meg?</li><li>Hvordan vil jeg føle meg når jeg lykkes?</li><li>Hva driver meg til å forbedre meg?</li></ul><p>Skriv ned svarene dine. Gå tilbake til dem når motivasjonen avtar.</p><h2 id="i-denne-delen" tabindex="-1">I denne delen <a class="header-anchor" href="#i-denne-delen" aria-label="Permalink to &quot;I denne delen&quot;">​</a></h2><ul><li><strong><a href="/no/utdanning/mål/smarte-mål">SMARTE mål i detalj</a></strong> - Dypdykk i å lage effektive mål</li><li><strong><a href="/no/utdanning/mål/planlegging">Lag treningsplanen din</a></strong> - Gjør mål om til handling</li></ul><h2 id="sammendrag-regler-for-malsetting" tabindex="-1">Sammendrag: Regler for målsetting <a class="header-anchor" href="#sammendrag-regler-for-malsetting" aria-label="Permalink to &quot;Sammendrag: Regler for målsetting&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regel nr. 1: Kontrollregelen</p><p><strong>Fokuser på prosessmål (hva du kontrollerer) fremfor resultatmål.</strong> Prosessmålinger fører til ytelsesmål, som igjen fører til resultatmål.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 2: SMART-regelen</p><p><strong>Mål må være spesifikke, målbare, oppnåelige, relevante og tidsbestemte.</strong> Vage mål gir vage resultater. SMARTE mål gir fremgang.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 3: Fordelingsregelen</p><p><strong>Store mål trenger kvartalsvise, månedlige og ukentlige milepæler.</strong> Del opp store mål i små, handlingsrettede steg du kan fullføre denne uken.</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 4: Forbindelsesregelen</p><p><strong>Knytt mål til ditt dypere «hvorfor».</strong> Når motivasjonen forsvinner, er det «hvorfor»-en din som holder deg i gang.</p></div><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Et mål uten en plan er bare et ønske.</p></blockquote><p>Sett deg klare mål. Bryt dem ned. Fokuser på det du kontrollerer. Spor fremgangen din.</p>',40))])}]]);export{m as __pageData,g as default};
